UPDATE products SET seo_description=CASE WHEN seo_description IN ('Meta Quest 3S. Choose the available condition and configuration below. Confirm supplied accessories and package contents with the store.','Meta Quest 3S combines standalone VR and full-colour passthrough with Fresnel lenses. It shares the XR2 Gen 2 platform with Quest 3 but uses different optics and display hardware.') OR coalesce(seo_description,'')='' THEN 'Meta Quest 3S combines standalone VR and full-colour passthrough with Fresnel lenses. It shares the XR2 Gen 2 platform with Quest 3 but uses different optics an' ELSE seo_description END,description='Meta Quest 3S combines standalone VR and full-colour passthrough with Fresnel lenses. It shares the XR2 Gen 2 platform with Quest 3 but uses different optics and display hardware.' WHERE slug='meta-quest-3s' AND description IN ('Meta Quest 3S. Choose the available condition and configuration below. Confirm supplied accessories and package contents with the store.','Meta Quest 3S combines standalone VR and full-colour passthrough with Fresnel lenses. It shares the XR2 Gen 2 platform with Quest 3 but uses different optics and display hardware.');
UPDATE product_details SET compatibility='Supported Meta Quest software. A Meta account is required; PC VR requires additional compatible hardware.' WHERE product_id=(SELECT id FROM products WHERE slug='meta-quest-3s') AND coalesce(compatibility,'') IN ('','','Supported Meta Quest software. A Meta account is required; PC VR requires additional compatible hardware.');
UPDATE product_details SET edition='Meta Quest 3S' WHERE product_id=(SELECT id FROM products WHERE slug='meta-quest-3s') AND coalesce(edition,'') IN ('','','Meta Quest 3S');
