UPDATE products SET seo_description=CASE WHEN seo_description IN ('Oculus Quest 2. Choose the available condition and configuration below. Confirm supplied accessories and package contents with the store.','The pre-owned Oculus Quest 2, also sold as Meta Quest 2, is a standalone VR headset with inside-out tracking. Choose the storage capacity of the actual unit. Its passthrough view is monochrome, unlike Quest 3 and 3S.') OR coalesce(seo_description,'')='' THEN 'The pre-owned Oculus Quest 2, also sold as Meta Quest 2, is a standalone VR headset with inside-out tracking. Choose the storage capacity of the actual unit. It' ELSE seo_description END,description='The pre-owned Oculus Quest 2, also sold as Meta Quest 2, is a standalone VR headset with inside-out tracking. Choose the storage capacity of the actual unit. Its passthrough view is monochrome, unlike Quest 3 and 3S.' WHERE slug='oculus-quest-2' AND description IN ('Oculus Quest 2. Choose the available condition and configuration below. Confirm supplied accessories and package contents with the store.','The pre-owned Oculus Quest 2, also sold as Meta Quest 2, is a standalone VR headset with inside-out tracking. Choose the storage capacity of the actual unit. Its passthrough view is monochrome, unlike Quest 3 and 3S.');
UPDATE product_details SET compatibility='Compatible Quest 2 software; some newer Quest titles require Quest 3/3S. A Meta account is required.' WHERE product_id=(SELECT id FROM products WHERE slug='oculus-quest-2') AND coalesce(compatibility,'') IN ('','','Compatible Quest 2 software; some newer Quest titles require Quest 3/3S. A Meta account is required.');
