INSERT OR IGNORE INTO product_images(id,product_id,variant_id,r2_key,alt_text,display_order,is_primary,is_transparent_asset,is_showcase_asset,width,height) SELECT 'catalogue-completion-oculus-quest-2-0',(SELECT id FROM products WHERE slug='oculus-quest-2'),NULL,'catalogue/inventory-oculus-quest-2.webp','Oculus Quest 2 — oculus-quest-2 product illustration',0,CASE WHEN NOT EXISTS(SELECT 1 FROM product_images WHERE product_id=(SELECT id FROM products WHERE slug='oculus-quest-2') AND is_primary=1) THEN 1 ELSE 0 END,1,1,1200,975 WHERE (SELECT id FROM products WHERE slug='oculus-quest-2') IS NOT NULL;
UPDATE products SET active=1 WHERE slug='oculus-quest-2' AND active=0 AND description IN ('Oculus Quest 2. Choose the available condition and configuration below. Confirm supplied accessories and package contents with the store.','The pre-owned Oculus Quest 2, also sold as Meta Quest 2, is a standalone VR headset with inside-out tracking. Choose the storage capacity of the actual unit. Its passthrough view is monochrome, unlike Quest 3 and 3S.') AND EXISTS(SELECT 1 FROM product_images WHERE product_id=products.id AND r2_key='catalogue/inventory-oculus-quest-2.webp');
